extends "res://htd/htd_test.gd"


func _run_tests() -> void:
	var script = load("res://advance_controller.gd")
	if not check("script_exists", script != null, "Lo script res://advance_controller.gd deve esistere"):
		return

	var ac = script.new()
	if not check("has_calc", has_function(ac, "calculate_auto_delay"), "Lo script deve contenere la funzione calculate_auto_delay"):
		ac.free()
		return
	if not check("has_read_count", has_function(ac, "get_read_count"), "Lo script deve contenere la funzione get_read_count"):
		ac.free()
		return
	if not check("has_reset", has_function(ac, "reset_read_history"), "Lo script deve contenere la funzione reset_read_history"):
		ac.free()
		return
	if not check("calc_args", function_argument_count(ac, "calculate_auto_delay") >= 2, "calculate_auto_delay deve accettare il parametro speed_multiplier"):
		ac.free()
		return

	check("read_count_initial", ac.get_read_count() == 0, "get_read_count() inizialmente deve restituire 0")

	ac.mark_line_as_read("res://c1.json", 0)
	ac.mark_line_as_read("res://c1.json", 1)
	var count: int = ac.get_read_count()
	check("read_count_after", count == 2, "get_read_count() dopo 2 righe lette deve restituire 2 (restituito %d)" % count)

	var char_delay: float = get_prop(ac, "CHAR_READ_DELAY", 0.05)
	var min_delay: float = get_prop(ac, "MIN_AUTO_DELAY", 1.5)
	var text := "1234567890".repeat(10)

	var expected_normal: float = maxf((text.length() * char_delay) / 1.0, min_delay)
	var delay_normal: float = ac.calculate_auto_delay(text, 1.0)
	check("delay_normal", absf(delay_normal - expected_normal) < 0.01, "calculate_auto_delay con speed 1.0 deve restituire %.2f (restituito %.2f)" % [expected_normal, delay_normal])

	var expected_fast: float = maxf((text.length() * char_delay) / 2.0, min_delay)
	var delay_fast: float = ac.calculate_auto_delay(text, 2.0)
	check("delay_fast", absf(delay_fast - expected_fast) < 0.01, "calculate_auto_delay con speed 2.0 deve restituire %.2f (restituito %.2f)" % [expected_fast, delay_fast])

	ac.reset_read_history()
	check("reset_history", ac.get_read_count() == 0, "reset_read_history() deve azzerare le righe lette")
	check("is_read_after_reset", ac.is_line_read("res://c1.json", 0) == false, "Dopo il reset la riga non deve più risultare letta")
	ac.free()

